definition.script:
pipeline {
    agent { label 'slave-1' }
    tools {
        maven "maven"
    }

    stages {
        stage('git checkout') {
            steps {
                git branch: 'main', credentialsId: 'eae984b2-1efc-4096-b178-ba4908e05b93', url: 'https://github.com/ksdkr/Boardgame.git'
            }
        }
        stage('compile') {
            steps {
                sh "mvn compile"
            }
        }
        stage('test') {
            steps {
               sh "mvn test"
            }
        }
        stage('build') {
            steps {
                sh "mvn package"
            }
        }

    }
}
